/** This string identifies a provider. */
export type ProviderId = string;

/** The broadcast uses this shared message-part delta payload. */
export type MessagePartDeltaData = PartDelta;

/** The broadcast uses this shared tool-output delta payload. */
export type ToolOutputDeltaData = PartDelta;

/** This revision is the SHA-256 of the file: 32 raw bytes, 64 hexadecimal characters. */
export type AgentConfigRev = string;

/** This hash identifies the exact instruction file bytes. */
export type InstructionHash = string;

/** This ID uses 64 raw bytes and 128 lowercase hexadecimal characters on the wire. */
export type CatalogRev = string;

/** This string identifies a model. */
export type ModelId = string;

/** This ID uses 16 raw bytes and 32 lowercase hexadecimal characters on the wire. */
export type SessionId = string;

/** This ID uses 32 raw bytes and 64 lowercase hexadecimal characters on the wire. */
export type LoginId = string;

/** This string identifies a request. */
export type RequestId = string;

/** This numeric ID identifies a message. */
export type MessageId = number;

/** This numeric ID identifies a run. */
export type RunId = number;

/** This numeric ID identifies an input. */
export type InputId = number;

/** This numeric ID identifies a message part. */
export type PartId = number;

/** This numeric value identifies an event sequence. */
export type Seq = number;

/** This numeric value identifies a session revision. */
export type SessionRevision = number;

/** This numeric value identifies a run configuration revision. */
export type ConfigRev = number;

/** This numeric ID correlates a frontend interaction with its answer. */
export type InteractionId = number;

export interface Methods {
  "agents.get": { paramsType: [Empty?]; returnType: AgentsGetResult };
  "agents.update": { paramsType: [AgentsUpdateParams]; returnType: AgentsGetResult };
  /** Establish the connection and negotiate the protocol version. */
  "initialize": { paramsType: [Empty?]; returnType: InitializeResult };
  /** List the sessions. */
  "session.list": { paramsType: [SessionListParams?]; returnType: SessionListResult };
  /** Read one session with its resident activity, or its durable idle activity. */
  "session.get": { paramsType: [SessionGetParams]; returnType: SessionListItem };
  /** Create a session. */
  "session.create": { paramsType: [CreateSession]; returnType: SessionResult };
  /** Update a session's mutable fields. */
  "session.patch": { paramsType: [SessionPatchParams]; returnType: Session };
  /** Remove a session. */
  "session.remove": { paramsType: [SessionRemoveParams]; returnType: Empty };
  /** Fork a session at a message. */
  "session.fork": { paramsType: [SessionForkParams]; returnType: Session };
  /** Compact a session's transcript. */
  "session.compact": { paramsType: [SessionCompactParams]; returnType: SessionCompactResult };
  /** Rewind a session to before a message. */
  "session.rewind": { paramsType: [SessionRewindParams]; returnType: Empty };
  /** Send user input to a session. */
  "session.send_input": { paramsType: [SessionSendInputParams]; returnType: SessionSendInputResult };
  /** Cancel a queued input. */
  "session.cancel_input": { paramsType: [SessionCancelInputParams]; returnType: SessionCancelInputResult };
  /** List the durable queued inputs of a session, oldest first. */
  "session.queue": { paramsType: [SessionQueueParams]; returnType: SessionQueueResult };
  /** Cancel the active run. */
  "session.cancel_run": { paramsType: [SessionCancelRunParams]; returnType: SessionCancelRunResult };
  /** Fetch a page from a session transcript. */
  "session.history": { paramsType: [SessionHistoryParams]; returnType: SessionHistoryResult };
  /** Fetch a session's run config. */
  "session.config": { paramsType: [SessionConfigParams]; returnType: SessionConfigResult };
  /** Rescan AGENTS.md and the skill roots and replace the stored snapshots of one session. */
  "session.reload_context": { paramsType: [SessionReloadContextParams]; returnType: SessionReloadContextResult };
  /** Read the body of one skill from the session catalog. */
  "skill.load": { paramsType: [SkillLoadParams]; returnType: SkillLoadResult };
  /** List the model catalog. */
  "catalog.list": { paramsType: [CatalogListParams?]; returnType: CatalogListResult };
  /** Read providers.json again and rebuild the catalog. */
  "catalog.reload": { paramsType: [Empty?]; returnType: CatalogReloadResult };
  /** List the local providers and the credential each one holds. */
  "auth.list": { paramsType: [Empty?]; returnType: AuthListResult };
  /** Set an API key for a provider. */
  "auth.set_api_key": { paramsType: [AuthSetApiKeyParams]; returnType: Empty };
  /** Begin a provider login flow. */
  "auth.login": { paramsType: [AuthLoginParams]; returnType: AuthLoginResult };
  /** Cancel an active login flow. */
  "auth.cancel_login": { paramsType: [AuthCancelLoginParams]; returnType: Empty };
  /** Remove the credential the engine holds for a provider. */
  "auth.remove": { paramsType: [AuthRemoveParams]; returnType: Empty };
  /** Answer one pending extension interaction. */
  "interaction.respond": { paramsType: [InteractionRespondParams]; returnType: Empty };
}

export interface Broadcasts {
  /** A session's summary metadata changed. */
  "session.summary_changed": SessionSummaryChangedData;
  /** A session's activity state changed. */
  "session.activity_changed": SessionActivityChangedData;
  /** The engine removed a session. */
  "session.removed": SessionRemovedData;
  /** The model catalog changed. */
  "catalog.changed": CatalogChangedData;
  /** The engine finished an authentication login flow. */
  "auth.login_finished": AuthLoginFinishedData;
  /** Authentication state changed. */
  "auth.changed": AuthChangedData;
  /** The engine sent an out-of-band notice. */
  "notice": Notice;
  /** The engine committed a message to a session transcript. */
  "message.committed": MessageCommittedData;
  /** A run started. */
  "run.started": RunStartedData;
  /** A run finished. */
  "run.done": RunDoneData;
  /** A session's run config changed. */
  "config.changed": ConfigChangedData;
  /** The engine truncated older transcript messages. */
  "transcript.truncated": TranscriptTruncatedData;
  /** A new streaming message started. */
  "message.started": MessageStartedData;
  /** The engine discarded an unfinished message. */
  "message.discarded": MessageDiscardedData;
  /** The engine added a part to a message. */
  "message.part_added": MessagePartAddedData;
  /** The engine sent more content for a message part. */
  "message.part_delta": MessagePartDeltaData;
  /** The engine attached final metadata to a stopped part. */
  "message.part_finalized": MessagePartFinalizedData;
  /** A tool call's state changed. */
  "tool.state_changed": ToolStateChangedData;
  /** The engine sent more output from a tool. */
  "tool.output_delta": ToolOutputDeltaData;
  /** The engine queued an input behind the active run. */
  "input.queued": InputQueuedData;
  /** The engine canceled a queued input. */
  "input.canceled": InputCanceledData;
  /** An extension asks the connected frontend to interact with the user. */
  "interaction.requested": InteractionRequestedData;
}

